function UIMainInteractionCookingMenuDialog:InitData()
    self._allBattleFoodData = {}

    local t = self:GetAllBattleFoodData()
    local _t = {}
    for k, v in pairs(t) do
        table.insert(_t, v)

        if table.count(_t) == PageFoodCount then
            table.insert(self._allBattleFoodData, _t)
            _t = {}
        elseif k == table.count(t) then 
            table.insert(self._allBattleFoodData, _t)
            _t = {}
        end
    end
end

--所有的套餐食品
function UIMainInteractionCookingMenuDialog:GetAllBattleFoodData()
    local t = CfUtils.GetCfTable(AutoIds.IdSetting2017)
    if not t then
        return {}
    end
    local _t = {}
    local useVo 
    for k, v in pairs(t) do
        local vo = CookingFoodVo.New()
        vo:FillVo(v)

        local isCurUse, num = CookingUtils.IsUseBattleFood(vo.id)
        if isCurUse then
            useVo = vo
        else
            table.insert(_t, vo)
        end
    end 

    for i = 1, #_t - 1 do
        for j = i + 1, #_t do
            local vo1 = _t[i]
            local vo2 = _t[j]
            local isChange = false
            if CookingUtils.IsUnlockFood(vo2.id) and not CookingUtils.IsUnlockFood(vo1.id) then
                isChange = true
            elseif CookingUtils.IsUnlockFood(vo2.id) and CookingUtils.IsUnlockFood(vo1.id) then
                if CookingUtils.IsCollectFood(vo2.id) and not CookingUtils.IsCollectFood(vo1.id) then
                    isChange = true
                else
                    isChange = checkNumber(vo2.id) < checkNumber(vo1.id)
                end
            else
                isChange = checkNumber(vo2.id) < checkNumber(vo1.id)
            end
            if isChange then
                local buffer = _t[i]
                _t[i] = _t[j]
                _t[j] = buffer
            end
        end
    end
    if useVo then
        table.insert(_t, 1, useVo)
    end
    --[[
    table.sort(_t, function(a, b)
        if (CookingUtils.IsUnlockFood(b.id) and CookingUtils.IsUnlockFood(a.id)) or ((not CookingUtils.IsUnlockFood(b.id)) and (not CookingUtils.IsUnlockFood(a.id))) then
            if not CookingUtils.IsCollectFood(b.id) and CookingUtils.IsCollectFood(a.id) then
                return true
            else
                return checkNumber(a.id) < checkNumber(b.id)
            end
        elseif not CookingUtils.IsUnlockFood(b.id) and CookingUtils.IsUnlockFood(a.id) then
            return false
        else
            return checkNumber(a.id) < checkNumber(b.id)
        end
        return false
    end)
    ]]
    return _t
end

--绘制
function UIMainInteractionCookingMenuDialog:RefreshFoodView()
    self._curPageFoodData = self:GetCurPageFoodData()
    if not self._isInitRoleView then
        self.LoopGridView:InitListView(#self._curPageFoodData, Bind(self, self.OnGetFoodCellByIndex))
        self.LoopGridView.mOnSnapNearestChanged = Bind(self, self.OnSnapNearestChanged)
        self._isInitRoleView = true
    else
        --GameUtils.ReloadData(self.LoopGridView, 0)
        GameUtils.ReloadData(self.LoopGridView, #self._curPageFoodData)
        self.LoopGridView:MovePanelToItemIndex(0)
    end
end

function UIMainInteractionCookingMenuDialog:OnSnapNearestChanged(listView, item)
    local ind = self.LoopGridView.CurSnapNearestItemIndex

    self._curPageInd = ind + 1
    --self:RefreshFoodView()
    self:RefreshArrow()
    self:RefreshPagePoints()
end

function UIMainInteractionCookingMenuDialog:OnGetFoodCellByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local data = self._curPageFoodData[index + 1]
    local pageGo = listView:NewListViewItem("Page")

    local goPar = pageGo.gameObject.transform:Find("ButtonLayout")
    local goInstantiate = goPar.transform:Find("Cell")

    for i = 1, goPar.transform.childCount do
        local go = goPar.transform:GetChild(i - 1)
        if go then
            KTool.SetActive(go, false)
        end
    end

    for k, v in pairs(data) do
        local go = goPar.transform:Find("cell"..k)
        if not go then
            go = CfUtils.InstantiateGo(goInstantiate, goPar)
            go.name = "cell"..k
        end
        KTool.SetActive(go, true)

        local scr = CfUtils.GetLuaScr(go, UIMainInteractionCookingMenuFoodNode)
        if scr then
            scr:Refresh(v, function()
                local t = {
                    goodsId = v.id,
                    consumeGoodsId = v.goodsConsum,
                    remainTime = 0,
                    consumeNum = v.goodsConsumNum,
                    maxBuyNum = 99,
                    buyCb = function(num)
                        comp:CookingBuyBattleCookingReq(v.id, num, function()
                            self:RefreshFoodView()
                            UIModule.OpenDialog({ id = Constants.UITypeIds.UICultivateLevelUpFinishDialog, parameters = {
                                foodId = v.id,
                                levelUpType = Constants.UICultivateLevelUpFinishType.CookingFood
                            }})
                        end)
                    end,
                }
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonBuyItemDialog, parameters = t}, {
                })
            end)
        end
    end

    return pageGo
end

