function UIMainInteractionCookingMenuDialog:OnBtnRight()
    local maxNum = table.count(self._allBattleFoodData)
    if self._curPageInd >= maxNum then
        return
    end
    self._curPageInd = self._curPageInd + 1
    print(self._curPageInd)
    self.LoopGridView:MovePanelToItemIndex(self._curPageInd - 1)

    --self:RefreshFoodView()
    self:RefreshArrow()
