function UIMainInteractionCookingMenuDialog:RefreshArrow()
    local lStatus, rStatus = 1, 1
    if self._curPageInd <= 1 then
        lStatus = 2
    end
    local maxNum = table.count(self._allBattleFoodData)
    if self._curPageInd >= maxNum then
        rStatus = 2
    end
    CfUtils.SetUISwitchImage(self.BtnLeft.transform:Find("ImgArrow"), lStatus)
    CfUtils.SetUISwitchImage(self.BtnRight.transform:Find("ImgArrow"), rStatus)

    local lRedPoint = false
    local rRedPoint = false
    local t
    if self._curPageInd > 1 then
        t = self._allBattleFoodData[self._curPageInd - 1]
        lRedPoint = self:IsMapHasNew(t)
    end

    if self._curPageInd < maxNum then
        t = self._allBattleFoodData[self._curPageInd + 1]
        rRedPoint = self:IsMapHasNew(t)
    end
    KTool.SetActive(self.BtnLeft.transform:Find("CommonRedPoint"), lRedPoint)
    KTool.SetActive(self.BtnRight.transform:Find("CommonRedPoint"), rRedPoint)
end

function UIMainInteractionCookingMenuDialog:RefreshPagePoints()
    local count = table.count(self._allBattleFoodData)
    if count <= 1 then
        KTool.SetActive(self.Page, false)
        return
    end
    for i = 1, count do
        local go = self.Page.transform:Find("point"..i)
        if not go then
            go = CfUtils.InstantiateGo(self.ImgSquare, self.Page)
            go.name = "point"..i
            KTool.SetActive(go, true)
        end
        local status = (checkNumber(self._curPageInd) == i) and 1 or 2
        CfUtils.SetUISwitchImage(go, status)
    end
end

--是否有新的数据
function UIMainInteractionCookingMenuDialog:IsMapHasNew(t)
    if not t then
        return false
    end
    for k, v in pairs(t) do
        if CookingUtils.IsNewRecipe(v.menu) then
            return true
        end
    end
    return false
end

